analyze.mjs.text:
// Classifies a set of per-path probe results (real HTTP responses, collected
// by probe.mjs's live requests) into a verdict about whether a target is
// publicly serving one of its own dotenv files.
//
// Pure function, no I/O, no network -- imported identically by the CLI
// (check.mjs) and the browser page (index.html).
//
// The one rule every function in this file is built around: a dotenv file's
// whole purpose is holding secrets, so this tool must never let a secret
// VALUE reach a report, a screen, a JSON blob, or anything a user might paste
// somewhere else. `parseEnvLines` is the only place a response body's
// content is inspected, and it returns key names and line shape only --
// never a value, never even a value's length or first character. Everything
// downstream of it operates on that redacted shape.
//
// What each classification means:
//
//   exposed    The path returned 200 and its body's non-comment,
//              non-blank lines are overwhelmingly KEY=VALUE shaped -- this
//              really is a dotenv file, not an unrelated page. Two
//              severities:
//                critical  at least one exposed key's *name* matches a
//                          common secret-naming pattern (SECRET, TOKEN,
//                          PASSWORD, API_KEY, and similar) -- the strongest
//                          signal available without ever reading the value
//                          itself.
//                danger    keys are exposed but none matched a
//                          secret-naming pattern -- still a real
//                          configuration-structure leak (which services are
//                          integrated, what environment this is), just
//                          without a name-level signal of a live credential.
//   blocked    The path returned a clean 401/403/404/410 -- not reachable.
//              A healthy outcome, whether the file was never there or a
//              server rule already denies it.
//   not-env    The path returned 200, but the body's shape does not look
//              like a dotenv file (mostly HTML, mostly prose, empty, or a
//              minority of lines are KEY=VALUE shaped) -- most likely a
//              soft-404 catch-all page. Reported separately from `blocked`
//              because it says something about the server's behaviour, but
//              it is not evidence of an exposure either way.
//   error      The request itself failed without a clean HTTP status
//              (network error, timeout, a browser's CORS-blocked "failed to
//              fetch"). Never read as either exposed or safe.

// A real dotenv line: optional leading whitespace, a shell-variable-shaped
// key, `=`, then anything (quoted or not) to end of line. Comments (`#...`)
// and blank lines are allowed and excluded from the shape ratio below rather
// than counted against it, since both are completely normal in a real file.
const ENV_LINE_RE = /^\s*[A-Za-z_][A-Za-z0-9_]*\s*=.*$/;
const COMMENT_OR_BLANK_RE = /^\s*(#.*)?$/;
const KEY_RE = /^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=/;

// Name-only pattern -- matched against the KEY, never the value. Presence of
// a name like this is a real, disclosable signal ("this file declares an AWS
// secret key") without ever touching what the value actually is.
const SECRET_NAME_RE = /(SECRET|PRIVATE|PASSWORD|PASSWD|PWD|TOKEN|API[_-]?KEY|ACCESS[_-]?KEY|CREDENTIAL|DATABASE_URL|DB_PASS|AUTH|SESSION_KEY|ENCRYPTION_KEY|CLIENT_SECRET|STRIPE|AWS_)/i;

/**
 * Parses a response body into KEY names only. Never returns, retains, or
 * exposes any VALUE text -- not the raw value, not its length, not its first
 * character. `envLineCount`/`totalContentLines` are what classification
 * needs to judge the file's *shape*; `keys` is what a report is allowed to
 * show a human.
 */
export function parseEnvLines(text) {
  const lines = typeof text === 'string' ? text.split(/\r?\n/) : [];
  const keys = [];
  let envLineCount = 0;
  let totalContentLines = 0;
  for (const line of lines) {
    if (COMMENT_OR_BLANK_RE.test(line)) continue;
    totalContentLines += 1;
    if (ENV_LINE_RE.test(line)) {
      envLineCount += 1;
      const m = KEY_RE.exec(line);
      if (m) keys.push(m[1]);
    }
  }
  return { keys, envLineCount, totalContentLines };
}

function looksLikeDotenv({ envLineCount, totalContentLines }, bodySample) {
  if (totalContentLines === 0) return false;
  if (/<html[\s>]|<!doctype html/i.test(bodySample)) return false;
  // A generous but real bar: most non-comment, non-blank lines must be
  // KEY=VALUE shaped. A prose 404 page or a JSON error body will fail this
  // even if it happens to contain one line with an "=" in it somewhere.
  return envLineCount / totalContentLines >= 0.6;
}

function classifyOne(result) {
  const { path } = result;
  if (!result.ok) {
    if (result.status === 401 || result.status === 403 || result.status === 404 || result.status === 410) {
      return { path, category: 'blocked', status: result.status, url: result.url, keys: [], secretKeys: [], error: null };
    }
    return { path, category: 'error', status: result.status ?? null, url: result.url, keys: [], secretKeys: [], error: result.error ?? 'request failed' };
  }

  const text = result.text ?? '';
  const parsed = parseEnvLines(text);
  if (!looksLikeDotenv(parsed, text)) {
    return { path, category: 'not-env', status: result.status, url: result.url, keys: [], secretKeys: [], error: null };
  }

  const secretKeys = parsed.keys.filter((k) => SECRET_NAME_RE.test(k));
  return {
    path,
    category: 'exposed',
    status: result.status,
    url: result.url,
    keys: parsed.keys,
    secretKeys,
    error: null,
  };
}

/**
 * @param {string} baseUrl - the site checked, for display only
 * @param {object[]} results - probe.mjs's per-path raw results
 */
export function buildReport(baseUrl, results) {
  const list = Array.isArray(results) ? results : [];
  const classified = list.map(classifyOne);

  const exposed = classified.filter((c) => c.category === 'exposed');
  const blocked = classified.filter((c) => c.category === 'blocked');
  const notEnv = classified.filter((c) => c.category === 'not-env');
  const errors = classified.filter((c) => c.category === 'error');

  const findings = exposed.map((c) => {
    const critical = c.secretKeys.length > 0;
    return {
      id: `dotenv-exposed-${c.path.replace(/[^a-z0-9]+/gi, '-')}`,
      severity: critical ? 'critical' : 'danger',
      path: c.path,
      url: c.url,
      keyCount: c.keys.length,
      // Key NAMES only -- see this file's header comment. Never a value.
      sampleKeys: c.keys.slice(0, 12),
      secretLikeKeys: c.secretKeys,
      title: critical
        ? `"${c.path}" is publicly readable and declares at least one likely secret`
        : `"${c.path}" is publicly readable`,
      detail: critical
        ? `${c.keys.length} variable(s) are declared, including ${c.secretKeys.length} whose name matches a ` +
          `common secret pattern (${c.secretKeys.slice(0, 5).join(', ')}${c.secretKeys.length > 5 ? ', …' : ''}). ` +
          `Values are never read by this report -- only the key names above, which is already enough to know a ` +
          `real credential is likely exposed.`
        : `${c.keys.length} variable(s) are declared. None of the key names matched a common secret pattern, ` +
          `but the file's configuration structure (which services are integrated, what environment this is) is ` +
          `still exposed. Values are never read by this report.`,
    };
  });

  const criticalCount = findings.filter((f) => f.severity === 'critical').length;
  const dangerCount = findings.filter((f) => f.severity === 'danger').length;
  const exposedCount = findings.length;

  return {
    baseUrl,
    pathsChecked: classified.length,
    classified,
    findings,
    blocked,
    notEnv,
    errors,
    criticalCount,
    dangerCount,
    exposedCount,
    incomplete: errors.length > 0,
    ok: exposedCount === 0,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: sends one GET request per well-known dotenv filename (.env,
// .env.local, .env.production, .env.production.local,
// .env.development.local) at a site's root and reports which ones are
// publicly readable -- verified against the real KEY=VALUE line shape of a
// dotenv file, not just an HTTP status, and reporting key NAMES only, never
// values. Your machine, real requests -- no request goes through this
// portfolio.
//
//   node check.mjs <site-url> [--json] [--timeout <ms>]
//
// Only run this against a site you own or are authorised to test -- treat it
// the same as you would `curl` aimed at someone else's server. This never
// sends anything but GET requests and never writes/modifies anything on the
// target.
//
// Exit code 0 when none of the checked paths is exposed; 1 when at least one
// is, or a request could not be completed at all.

import { checkSite } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Site: ${report.baseUrl}`);
  lines.push(`Paths checked: ${report.pathsChecked}`);
  lines.push('');

  if (report.findings.length === 0) {
    lines.push('No exposed dotenv file found among the ones this tool checks.');
  } else {
    for (const f of report.findings) {
      lines.push(`!! [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push(`     url: ${f.url}`);
      lines.push(`     keys (names only, never values): ${f.sampleKeys.join(', ')}${f.keyCount > f.sampleKeys.length ? ', …' : ''}`);
      lines.push('');
    }
  }

  if (report.blocked.length > 0) {
    lines.push(`${report.blocked.length} path(s) cleanly blocked (401/403/404) -- a healthy outcome: ${report.blocked.map((c) => c.path).join(', ')}`);
  }
  if (report.notEnv.length > 0) {
    lines.push(`${report.notEnv.length} path(s) returned 200 but did not look like a dotenv file (likely a soft-404 page): ${report.notEnv.map((c) => c.path).join(', ')}`);
  }
  if (report.errors.length > 0) {
    lines.push(`${report.errors.length} path(s) could not be checked: ${report.errors.map((c) => `${c.path} (${c.error})`).join('; ')}`);
  }

  lines.push('');
  lines.push(
    'This is evidence from the requests above, not a full security audit -- see README.md for ' +
      'what this tool does and does not check.',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  let siteUrl = null;
  let json = false;
  let timeoutMs;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') json = true;
    else if (argv[i] === '--timeout') timeoutMs = Number(argv[++i]);
    else if (!argv[i].startsWith('--') && siteUrl === null) siteUrl = argv[i];
  }
  return { siteUrl, json, timeoutMs };
}

/** Pure orchestration: given a checkSite function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `checkSiteFn` instead of hitting the network. */
export async function runCheck(siteUrl, { checkSiteFn = checkSite, timeoutMs } = {}) {
  const { results } = await checkSiteFn(siteUrl, timeoutMs ? { timeoutMs } : undefined);
  return buildReport(siteUrl, results);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.siteUrl) {
    console.error('Usage: node check.mjs <site-url> [--json] [--timeout <ms>]');
    console.error('Only run this against a site you own or are authorised to test.');
    process.exit(2);
  }
  try {
    // eslint-disable-next-line no-new
    new URL(args.siteUrl);
  } catch {
    console.error(`Not a valid URL: ${args.siteUrl}`);
    process.exit(2);
  }

  const report = await runCheck(args.siteUrl, { timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Real-network layer: sends one plain GET request to each of a short list of
// well-known dotenv filenames at a site's root and returns exactly what came
// back -- status and a byte-capped body, nothing else. Deliberately the same
// module imported unmodified by the CLI (Node 22's built-in `fetch`) and by
// the browser page (`index.html` imports it directly), the same shape
// `ventures/git-exposure-check/probe.mjs` documents.
//
// This module never inspects, extracts, or reports any VALUE from a response
// body -- see analyze.mjs for why that matters here specifically. It only
// fetches; classification (and the value-redaction that classification
// depends on) happens there.
//
// Whether a browser run can complete depends on the target's own CORS policy
// for a plain cross-origin GET -- most servers do not send permissive CORS
// headers on arbitrary static paths, so a cross-origin browser fetch commonly
// fails with a generic, status-less network error. This module never guesses
// which cause that was; it reports it as an unclassified `error`. The CLI,
// run from a machine rather than a browser tab, is not subject to CORS at all
// and is the one path guaranteed to complete.
//
// This module only ever talks to the one base URL the caller names, at the
// fixed list of paths below. It sends nothing anywhere but GET requests to a
// host the caller already supplied.

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  'dotenv-exposure-check/1 (+https://duncan-haywood.github.io/monorepo-projects/dotenv-exposure-check/)';
// A real dotenv file is normally a handful of short lines. This cap is
// generous enough to still classify a real exposure while bounding what this
// tool ever holds in memory or could be made to download on repeat.
const MAX_BODY_BYTES = 1_000_000;

// The specific dotenv filenames checked, in the precedence order Next.js's
// own documentation defines for them (.env, then environment-specific, then
// the *.local overrides that are meant to never be committed at all) --
// `.env.local` and the two `*.local` variants are the ones most likely to
// carry a real developer's own secrets rather than committed defaults.
export const ENV_PATHS = [
  '.env',
  '.env.local',
  '.env.production',
  '.env.production.local',
  '.env.development.local',
];

async function timedFetch(url, init, timeoutMs, fetchImpl) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  if (typeof doFetch !== 'function') {
    throw new Error('no fetch implementation available in this environment');
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await doFetch(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

async function readCapped(res, maxBytes) {
  if (!res.body?.getReader) {
    const text = await res.text();
    return text.length > maxBytes ? text.slice(0, maxBytes) : text;
  }
  const reader = res.body.getReader();
  const chunks = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    chunks.push(value);
    if (total >= maxBytes) {
      try { await reader.cancel(); } catch { /* best effort */ }
      break;
    }
  }
  const combined = new Uint8Array(Math.min(total, maxBytes));
  let offset = 0;
  for (const chunk of chunks) {
    const room = combined.length - offset;
    if (room <= 0) break;
    combined.set(room < chunk.length ? chunk.subarray(0, room) : chunk, offset);
    offset += Math.min(chunk.length, room);
  }
  return new TextDecoder('utf-8', { fatal: false }).decode(combined);
}

/** One GET request to `${baseUrl}/${path}`, capped and never throwing on an
 * ordinary HTTP or network failure -- those come back as `ok: false` with
 * `error` set, so a caller can tell "confirmed absent/blocked" (a clean
 * status) apart from "could not confirm either way" (a network error). */
export async function fetchEnvPath(baseUrl, path, { timeoutMs = DEFAULT_TIMEOUT_MS, fetchImpl } = {}) {
  const url = new URL(path, baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`).toString();
  let res;
  try {
    res = await timedFetch(
      url,
      { method: 'GET', headers: { 'user-agent': USER_AGENT, accept: '*/*' } },
      timeoutMs,
      fetchImpl,
    );
  } catch (err) {
    return { path, url, ok: false, status: null, text: null, error: err.message ?? String(err) };
  }
  if (!res.ok) {
    return { path, url, ok: false, status: res.status, text: null, error: `HTTP ${res.status}` };
  }
  let text;
  try {
    text = await readCapped(res, MAX_BODY_BYTES);
  } catch (err) {
    return { path, url, ok: false, status: res.status, text: null, error: err.message ?? String(err) };
  }
  return { path, url, ok: true, status: res.status, text, error: null };
}

/** Full run: fetch every path in `ENV_PATHS` (or an explicit subset) against
 * `baseUrl`, in parallel. Never throws on a per-path failure -- every path
 * gets a result, `ok: false` and all. */
export async function checkSite(baseUrl, { paths = ENV_PATHS, timeoutMs, fetchImpl } = {}) {
  if (!baseUrl) throw new Error('a base URL is required');
  const results = await Promise.all(
    paths.map((path) => fetchEnvPath(baseUrl, path, { timeoutMs, fetchImpl })),
  );
  return { baseUrl, results };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// target URL, the pasted probe JSON, or anything about what was checked --
// that is exactly the kind of thing that must not be transmitted anywhere,
// and this tool never reads it off the visitor's machine either.

const STORAGE_KEY = 'dotenv-exposure-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
